const body = $json.body || {};

const nome = String(body.nome_aluno || "")
  .trim()
  .toLowerCase();

const turma = String(body.turma || "")
  .trim()
  .toUpperCase()
  .replace(/[-_.]/g, " ")
  .replace(/\s+/g, " ");

// Aceita 3dsa, 3DSA, 2admb etc.
const match = turma.match(/^([123])\s*(DS|ADM)\s*([AB])$/);

const turmaFormatada = match
  ? `${match[1]} ${match[2]} ${match[3]}`
  : turma;

return [{
  json: {
    nome_aluno: nome,
    turma: turmaFormatada
  }
}];

const registros = $input.all();
const consulta = $('Preparar Consulta').first().json;

function normalizar(texto) {
  return String(texto || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/\s+/g, " ");
}

const nomeBuscado = normalizar(consulta.nome_aluno);
const turmaBuscada = normalizar(consulta.turma);

let encontrados = registros.filter(item => {
  const nome = normalizar(item.json.nome_aluno);
  const turma = normalizar(item.json.turma);
  const nomeCorreto = !nomeBuscado || nome.includes(nomeBuscado);
  const turmaCorreta = !turmaBuscada || turma === turmaBuscada;
  return nomeCorreto && turmaCorreta;
});

if (encontrados.length === 0) {
  return [{ json: { encontrado: false, nome_aluno: consulta.nome_aluno, turma: consulta.turma } }];
}

// Consulta vazia é usada pelas análises do site para recuperar todos os registros.
if (!nomeBuscado) return encontrados;

// Correspondência exata tem prioridade sobre correspondências parciais.
const exatos = encontrados.filter(item => normalizar(item.json.nome_aluno) === nomeBuscado);
if (exatos.length) encontrados = exatos;

const pessoas = new Map();
for (const item of encontrados) {
  const nomeOriginal = String(item.json.nome_aluno || "").trim();
  const id = normalizar(nomeOriginal);
  if (!pessoas.has(id)) pessoas.set(id, { nome_aluno: nomeOriginal, turmas: new Set() });
  pessoas.get(id).turmas.add(String(item.json.turma || "Não informado").trim());
}

if (pessoas.size > 1) {
  const candidatos = [...pessoas.values()].map(p => ({
    nome_aluno: p.nome_aluno,
    turmas: [...p.turmas]
  }));
  return [{ json: { encontrado: false, ambiguo: true, candidatos } }];
}

return encontrados;

const registros = $input.all().map(item => item.json);

if (registros.length === 1 && registros[0]?.ambiguo) {
  return [{ json: registros[0] }];
}

if (
  registros.length === 0 ||
  registros[0]?.encontrado === false ||
  !registros[0]?.nome_aluno
) {
  return [{ json: { encontrado: false, registros: [] } }];
}

// Remove duplicatas idênticas apenas da resposta exibida.
const vistos = new Set();
const unicos = registros.filter(r => {
  const chave = [r.nome_aluno,r.turma,r.data_saida,r.horario_saida,r.responsavel,r.motivo,r.status]
    .map(v => String(v ?? '').trim().toLowerCase()).join('|');
  if (vistos.has(chave)) return false;
  vistos.add(chave); return true;
});

unicos.sort((a, b) => {
  const parse = (data, hora) => {
    const [d, m, y] = String(data || "").split("/");
    return new Date(`${y}-${m}-${d}T${hora || "00:00"}:00`);
  };
  return parse(b.data_saida, b.horario_saida) - parse(a.data_saida, a.horario_saida);
});

const turmas = [...new Set(unicos.map(r => r.turma).filter(Boolean))];
return [{
  json: {
    encontrado: true,
    nome_aluno: unicos[0].nome_aluno,
    turma: turmas.length === 1 ? turmas[0] : turmas.join(', '),
    quantidade: unicos.length,
    registros: unicos
  }
}];
